/* Seeded two-layer MLP, mini-batch SGD, analytic backpropagation. No remote compute. */
(function(root){
function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function dataset(kind='moons',noise=.12,seed=42,n=400){const r=rng(seed),out=[];for(let i=0;i<n;i++){let y=i%2,x1,x2;const t=r()*Math.PI;if(kind==='moons'){x1=y?1-Math.cos(t):Math.cos(t);x2=y?.5-Math.sin(t):Math.sin(t);x1=(x1-.5)/1.5;x2=(x2-.25)/1.2}else if(kind==='circles'){const a=r()*2*Math.PI,rad=y?.38:.85;x1=Math.cos(a)*rad;x2=Math.sin(a)*rad}else{x1=r()*2-1;x2=r()*2-1;y=(x1*x2>0)?1:0}x1+=(r()+r()+r()-1.5)*noise;x2+=(r()+r()+r()-1.5)*noise;out.push({x:[x1,x2],y})}for(let i=out.length-1;i>0;i--){let j=Math.floor(r()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return{train:out.slice(0,n*.7),val:out.slice(n*.7,n*.85),test:out.slice(n*.85),all:out}}
class MLP{constructor(hidden=12,seed=42){this.h=hidden;this.r=rng(seed);this.w1=Array.from({length:hidden},()=>[(this.r()-.5)*2,(this.r()-.5)*2]);this.b1=Array(hidden).fill(0);this.w2=Array.from({length:hidden},()=>(this.r()-.5)*2/Math.sqrt(hidden));this.b2=0}forward(x){let a=this.w1.map((w,j)=>Math.tanh(w[0]*x[0]+w[1]*x[1]+this.b1[j]));let z=this.b2+a.reduce((s,v,j)=>s+v*this.w2[j],0);let p=1/(1+Math.exp(-Math.max(-40,Math.min(40,z))));return{a,p}}trainEpoch(data,lr,batch){const order=[...data];for(let i=order.length-1;i>0;i--){const j=Math.floor(this.r()*(i+1));[order[i],order[j]]=[order[j],order[i]]}for(let offset=0;offset<order.length;offset+=batch){let g1=Array.from({length:this.h},()=>[0,0]),gb1=Array(this.h).fill(0),g2=Array(this.h).fill(0),gb2=0;const chunk=order.slice(offset,offset+batch);for(const d of chunk){const{a,p}=this.forward(d.x),dz=p-d.y;gb2+=dz;for(let j=0;j<this.h;j++){g2[j]+=dz*a[j];let dh=dz*this.w2[j]*(1-a[j]*a[j]);g1[j][0]+=dh*d.x[0];g1[j][1]+=dh*d.x[1];gb1[j]+=dh}}let s=lr/chunk.length;for(let j=0;j<this.h;j++){this.w1[j][0]-=s*g1[j][0];this.w1[j][1]-=s*g1[j][1];this.b1[j]-=s*gb1[j];this.w2[j]-=s*g2[j]}this.b2-=s*gb2}}evaluate(data){let loss=0,ok=0,cm=[0,0,0,0];for(const d of data){const p=Math.max(1e-9,Math.min(1-1e-9,this.forward(d.x).p)),pred=+(p>=.5);loss-=d.y*Math.log(p)+(1-d.y)*Math.log(1-p);ok+=pred===d.y;cm[d.y*2+pred]++}return{loss:loss/data.length,accuracy:ok/data.length,cm}}weights(){return{hidden:this.h,w1:this.w1,b1:this.b1,w2:this.w2,b2:this.b2}}}
root.TrainEngine={rng,dataset,MLP};if(typeof module!=='undefined')module.exports=root.TrainEngine;
})(typeof window!=='undefined'?window:globalThis);
